const resumeText = $json.text ?? $json.data ?? '';

const webhook = $('Candidate Uploads Resume (Webhook)1').first().json;

// Use the body if it exists, otherwise use the whole webhook JSON
const webhookData = webhook.body ?? webhook;

// Guard: flag suspiciously short/garbled extraction (common with .docx raw-text reads)
const trimmed = (resumeText || '').trim();
const extractionLooksBad = trimmed.length < 40;

return [
  {
    json: {
      ...webhookData,
      resumeText,
      extractionLooksBad,
      pdfInfo: $json.info ?? {},
      numPages: $json.numpages ?? 0,
      pdfVersion: $json.version ?? '',
    },
  },
];

const raw = $json.output;
const prepData = $('Prepare Data').first().json;

let parsed = null;
let parseError = null;

try {
  const cleaned = (raw || '').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (err) {
  parseError = err.message;
}

// Safety net: if the model returned invalid JSON, don't crash the workflow.
// Fall back to a zero-score record flagged for manual review, using data
// we already captured from the original submission.
if (!parsed) {
  parsed = {
    candidateName: prepData.fullName || '',
    candidateEmail: prepData.email || '',
    skills: [],
    experience: [],
    education: [],
    certifications: [],
    totalYearsExperience: 0,
    matchScore: 0,
    missingSkills: [],
    strengths: [],
    weaknesses: [`AI response could not be parsed as JSON and requires manual review. Error: ${parseError}`]
  };
}

return [
  {
    json: {
      candidateName: parsed.candidateName,
      candidateEmail: parsed.candidateEmail,
      position: prepData.position || '',
      matchScore: parsed.matchScore,
      totalYearsExperience: parsed.totalYearsExperience,
      skills: (parsed.skills || []).join(", "),
      certifications: (parsed.certifications || []).join(", "),
      missingSkills: (parsed.missingSkills || []).join(", "),
      strengths: (parsed.strengths || []).join("\n"),
      weaknesses: (parsed.weaknesses || []).join("\n"),
      experience: (parsed.experience || [])
        .map(e => `${e.role} - ${e.company} (${e.years} years)`)
        .join("\n"),
      education: (parsed.education || [])
        .map(e => `${e.degree} - ${e.institution} (${e.year})`)
        .join("\n"),
      evaluatedAt: new Date().toISOString(),
      parseError: parseError,
      rawAIOutput: parseError ? raw : ''
    }
  }
];

// Interview hours: 10:00 AM - 7:00 PM
const DAY_START_HOUR = 10;
const DAY_END_HOUR = 19;
const SLOT_DURATION_MIN = 30;
const MAX_DAYS_TO_CHECK = 45;

// Calendar events from previous node (Get Existing Interview Events)
const events = $input.all().map(item => item.json);

function isWeekend(dt) {
  return dt.weekday === 6 || dt.weekday === 7;
}

function overlapsExisting(candidateStart, candidateEnd) {
  const startMs = candidateStart.toMillis();
  const endMs = candidateEnd.toMillis();

  return events.some(ev => {
    const evStartRaw = ev.start?.dateTime || ev.start?.date;
    const evEndRaw = ev.end?.dateTime || ev.end?.date;

    if (!evStartRaw || !evEndRaw) return false;

    const evStartMs = new Date(evStartRaw).getTime();
    const evEndMs = new Date(evEndRaw).getTime();

    return startMs < evEndMs && endMs > evStartMs;
  });
}

let day = $now
  .plus({ days: 1 })
  .set({
    hour: DAY_START_HOUR,
    minute: 0,
    second: 0,
    millisecond: 0
  });

let found = null;
let daysChecked = 0;

while (!found && daysChecked < MAX_DAYS_TO_CHECK) {

  if (!isWeekend(day)) {

    let slotStart = day.set({
      hour: DAY_START_HOUR,
      minute: 0
    });

    const dayEnd = day.set({
      hour: DAY_END_HOUR,
      minute: 0
    });

    while (slotStart.plus({ minutes: SLOT_DURATION_MIN }) <= dayEnd) {

      const slotEnd = slotStart.plus({
        minutes: SLOT_DURATION_MIN
      });

      if (!overlapsExisting(slotStart, slotEnd)) {
        found = {
          start: slotStart,
          end: slotEnd
        };
        break;
      }

      slotStart = slotStart.plus({
        minutes: SLOT_DURATION_MIN
      });
    }
  }

  day = day.plus({
    days: 1
  }).set({
    hour: DAY_START_HOUR,
    minute: 0,
    second: 0,
    millisecond: 0
  });

  daysChecked++;
}

// FIX: pull the candidate record from 'Score > 80?' — NOT from $input,
// since this node's direct input is the calendar-events list, not the candidate.
const record = $('Score > 80?1').first().json;

if (!found) {
  return [{
    json: {
      ...record,
      slotFound: false,
      interviewSlotStart: null,
      interviewSlotEnd: null
    }
  }];
}

return [{
  json: {
    ...record,
    slotFound: true,
    interviewSlotStart: found.start.toISO(),
    interviewSlotEnd: found.end.toISO()
  }
}];

